-- rail_liquidity_position: Intraday liquidity position per nostro / rail, refreshed from statements and flows
CREATE TABLE rail_liquidity_position (
  id                           uuid PRIMARY KEY DEFAULT uuidv7(),
  tenant_id                    uuid NOT NULL,
  created_at                   timestamptz NOT NULL DEFAULT now(),
  created_by                   varchar(64),
  updated_at                   timestamptz NOT NULL DEFAULT now(),
  updated_by                   varchar(64),
  row_version                  integer NOT NULL DEFAULT 1,
  nostro_account_id            uuid NOT NULL REFERENCES nostro_account(id),
  as_of                        timestamptz NOT NULL,
  opening_balance              numeric(28,8) NOT NULL,
  projected_inflows            numeric(28,8) NOT NULL DEFAULT 0,
  projected_outflows           numeric(28,8) NOT NULL DEFAULT 0,
  current_balance              numeric(28,8) NOT NULL,
  available_liquidity          numeric(28,8) NOT NULL,
  currency                     char(3) NOT NULL,
  breach                       boolean NOT NULL DEFAULT false,
  custom_field_1               varchar(500),
  custom_field_2               varchar(500),
  custom_field_3               varchar(500),
  custom_field_4               varchar(500),
  custom_field_5               varchar(500)
);
COMMENT ON TABLE rail_liquidity_position IS 'Intraday liquidity position per nostro / rail, refreshed from statements and flows';
COMMENT ON COLUMN rail_liquidity_position.id IS 'Unique id (UUIDv7, time-ordered)';
COMMENT ON COLUMN rail_liquidity_position.tenant_id IS 'Owning tenant; enforced by row-level security';
COMMENT ON COLUMN rail_liquidity_position.created_at IS 'Creation time';
COMMENT ON COLUMN rail_liquidity_position.created_by IS 'Principal that created the row';
COMMENT ON COLUMN rail_liquidity_position.updated_at IS 'Last update time';
COMMENT ON COLUMN rail_liquidity_position.updated_by IS 'Principal that last updated the row';
COMMENT ON COLUMN rail_liquidity_position.row_version IS 'Optimistic lock version; send as If-Match';
COMMENT ON COLUMN rail_liquidity_position.nostro_account_id IS 'Account';
COMMENT ON COLUMN rail_liquidity_position.as_of IS 'Position time';
COMMENT ON COLUMN rail_liquidity_position.opening_balance IS 'Opening balance';
COMMENT ON COLUMN rail_liquidity_position.projected_inflows IS 'Expected inflows';
COMMENT ON COLUMN rail_liquidity_position.projected_outflows IS 'Expected outflows';
COMMENT ON COLUMN rail_liquidity_position.current_balance IS 'Current balance';
COMMENT ON COLUMN rail_liquidity_position.available_liquidity IS 'Balance minus reserved outflows';
COMMENT ON COLUMN rail_liquidity_position.currency IS 'Currency';
COMMENT ON COLUMN rail_liquidity_position.breach IS 'Below minimum balance';
COMMENT ON COLUMN rail_liquidity_position.custom_field_1 IS 'Tenant-defined custom field 1; label, type and validation configured in custom_field_definition';
COMMENT ON COLUMN rail_liquidity_position.custom_field_2 IS 'Tenant-defined custom field 2; label, type and validation configured in custom_field_definition';
COMMENT ON COLUMN rail_liquidity_position.custom_field_3 IS 'Tenant-defined custom field 3; label, type and validation configured in custom_field_definition';
COMMENT ON COLUMN rail_liquidity_position.custom_field_4 IS 'Tenant-defined custom field 4; label, type and validation configured in custom_field_definition';
COMMENT ON COLUMN rail_liquidity_position.custom_field_5 IS 'Tenant-defined custom field 5; label, type and validation configured in custom_field_definition';
CREATE INDEX ix_rail_liquidity_position_tenant ON rail_liquidity_position (tenant_id, created_at);
CREATE INDEX ix_rail_liquidity_position_nostro_account_id ON rail_liquidity_position (nostro_account_id);
ALTER TABLE rail_liquidity_position ENABLE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON rail_liquidity_position USING (tenant_id = current_setting('app.tenant_id')::uuid);
CREATE TRIGGER trg_rail_liquidity_position_touch BEFORE UPDATE ON rail_liquidity_position FOR EACH ROW EXECUTE FUNCTION touch_row();

-- rail_participant: Bank / PSP directory entry (BIC, clearing codes, rail reachability)
CREATE TABLE rail_participant (
  id                           uuid PRIMARY KEY DEFAULT uuidv7(),
  created_at                   timestamptz NOT NULL DEFAULT now(),
  created_by                   varchar(64),
  updated_at                   timestamptz NOT NULL DEFAULT now(),
  updated_by                   varchar(64),
  row_version                  integer NOT NULL DEFAULT 1,
  bic                          varchar(11),
  clearing_system              varchar(16),
  clearing_id                  varchar(35),
  name                         varchar(140) NOT NULL,
  country                      char(2) NOT NULL,
  reachable_rails              jsonb,
  valid_from                   date,
  valid_to                     date,
  source                       varchar(32),
  custom_field_1               varchar(500),
  custom_field_2               varchar(500),
  custom_field_3               varchar(500),
  custom_field_4               varchar(500),
  custom_field_5               varchar(500)
);
COMMENT ON TABLE rail_participant IS 'Bank / PSP directory entry (BIC, clearing codes, rail reachability)';
COMMENT ON COLUMN rail_participant.id IS 'Unique id (UUIDv7, time-ordered)';
COMMENT ON COLUMN rail_participant.created_at IS 'Creation time';
COMMENT ON COLUMN rail_participant.created_by IS 'Principal that created the row';
COMMENT ON COLUMN rail_participant.updated_at IS 'Last update time';
COMMENT ON COLUMN rail_participant.updated_by IS 'Principal that last updated the row';
COMMENT ON COLUMN rail_participant.row_version IS 'Optimistic lock version; send as If-Match';
COMMENT ON COLUMN rail_participant.bic IS 'BIC';
COMMENT ON COLUMN rail_participant.clearing_system IS 'Clearing system (GBDSC, USABA, INFSC, BRPIX...)';
COMMENT ON COLUMN rail_participant.clearing_id IS 'Sort code, ABA routing number, IFSC, ISPB';
COMMENT ON COLUMN rail_participant.name IS 'Institution name';
COMMENT ON COLUMN rail_participant.country IS 'Country';
COMMENT ON COLUMN rail_participant.reachable_rails IS 'Rail codes the participant is reachable on';
COMMENT ON COLUMN rail_participant.valid_from IS 'Directory validity start';
COMMENT ON COLUMN rail_participant.valid_to IS 'Directory validity end';
COMMENT ON COLUMN rail_participant.source IS 'SWIFT_BIC_DIRECTORY, EPC_REGISTER, FED_E_PAYMENTS, RBI, BCB';
COMMENT ON COLUMN rail_participant.custom_field_1 IS 'Tenant-defined custom field 1; label, type and validation configured in custom_field_definition';
COMMENT ON COLUMN rail_participant.custom_field_2 IS 'Tenant-defined custom field 2; label, type and validation configured in custom_field_definition';
COMMENT ON COLUMN rail_participant.custom_field_3 IS 'Tenant-defined custom field 3; label, type and validation configured in custom_field_definition';
COMMENT ON COLUMN rail_participant.custom_field_4 IS 'Tenant-defined custom field 4; label, type and validation configured in custom_field_definition';
COMMENT ON COLUMN rail_participant.custom_field_5 IS 'Tenant-defined custom field 5; label, type and validation configured in custom_field_definition';
CREATE INDEX ix_rail_participant_bic ON rail_participant (bic);
CREATE INDEX ix_rail_participant_clearing_id ON rail_participant (clearing_id);
CREATE TRIGGER trg_rail_participant_touch BEFORE UPDATE ON rail_participant FOR EACH ROW EXECUTE FUNCTION touch_row();

-- rail_message: Raw message exchanged with a rail (pacs, pain, camt, ISO 8583, NACHA). Append-only, for audit and replay.
CREATE TABLE rail_message (
  id                           uuid PRIMARY KEY DEFAULT uuidv7(),
  tenant_id                    uuid NOT NULL,
  created_at                   timestamptz NOT NULL DEFAULT now(),
  created_by                   varchar(64),
  payment_rail_id              uuid NOT NULL REFERENCES payment_rail(id),
  direction                    varchar(40) NOT NULL CHECK (direction IN ('INBOUND', 'OUTBOUND')),
  message_type                 varchar(32) NOT NULL,
  message_id                   varchar(64) NOT NULL,
  end_to_end_id                varchar(35),
  payment_id                   uuid,
  rail_settlement_batch_id     uuid REFERENCES rail_settlement_batch(id),
  replay_of_id                 uuid REFERENCES rail_message(id),
  status                       varchar(40) NOT NULL CHECK (status IN ('RECEIVED', 'PARSED', 'SENT', 'ACKNOWLEDGED', 'NACKED', 'FAILED')),
  payload_uri                  varchar(500) NOT NULL,
  payload_hash                 varchar(64) NOT NULL,
  payload                      text,
  signature_valid              boolean,
  error                        text,
  custom_field_1               varchar(500),
  custom_field_2               varchar(500),
  custom_field_3               varchar(500),
  custom_field_4               varchar(500),
  custom_field_5               varchar(500)
);
COMMENT ON TABLE rail_message IS 'Raw message exchanged with a rail (pacs, pain, camt, ISO 8583, NACHA). Append-only, for audit and replay.';
COMMENT ON COLUMN rail_message.id IS 'Unique id (UUIDv7, time-ordered)';
COMMENT ON COLUMN rail_message.tenant_id IS 'Owning tenant; enforced by row-level security';
COMMENT ON COLUMN rail_message.created_at IS 'Creation time';
COMMENT ON COLUMN rail_message.created_by IS 'Principal that created the row';
COMMENT ON COLUMN rail_message.payment_rail_id IS 'Rail';
COMMENT ON COLUMN rail_message.direction IS 'Inbound or outbound';
COMMENT ON COLUMN rail_message.message_type IS 'e.g. pacs.008.001.08, pacs.002, camt.056, pain.001';
COMMENT ON COLUMN rail_message.message_id IS 'Message id (MsgId)';
COMMENT ON COLUMN rail_message.end_to_end_id IS 'End-to-end id of the (original) transaction';
COMMENT ON COLUMN rail_message.payment_id IS 'Related payment';
COMMENT ON COLUMN rail_message.rail_settlement_batch_id IS 'Batch, for batch rails';
COMMENT ON COLUMN rail_message.replay_of_id IS 'Message this one replays';
COMMENT ON COLUMN rail_message.status IS 'Processing status';
COMMENT ON COLUMN rail_message.payload_uri IS 'Encrypted payload location (object storage)';
COMMENT ON COLUMN rail_message.payload_hash IS 'SHA-256 of the payload';
COMMENT ON COLUMN rail_message.payload IS 'Raw payload (served only through GET /payload)';
COMMENT ON COLUMN rail_message.signature_valid IS 'Signature verification result';
COMMENT ON COLUMN rail_message.error IS 'Error detail';
COMMENT ON COLUMN rail_message.custom_field_1 IS 'Tenant-defined custom field 1; label, type and validation configured in custom_field_definition';
COMMENT ON COLUMN rail_message.custom_field_2 IS 'Tenant-defined custom field 2; label, type and validation configured in custom_field_definition';
COMMENT ON COLUMN rail_message.custom_field_3 IS 'Tenant-defined custom field 3; label, type and validation configured in custom_field_definition';
COMMENT ON COLUMN rail_message.custom_field_4 IS 'Tenant-defined custom field 4; label, type and validation configured in custom_field_definition';
COMMENT ON COLUMN rail_message.custom_field_5 IS 'Tenant-defined custom field 5; label, type and validation configured in custom_field_definition';
CREATE INDEX ix_rail_message_tenant ON rail_message (tenant_id, created_at);
CREATE INDEX ix_rail_message_payment_rail_id ON rail_message (payment_rail_id);
CREATE INDEX ix_rail_message_message_id ON rail_message (message_id);
CREATE INDEX ix_rail_message_end_to_end_id ON rail_message (end_to_end_id);
CREATE INDEX ix_rail_message_payment_id ON rail_message (payment_id);
CREATE INDEX ix_rail_message_rail_settlement_batch_id ON rail_message (rail_settlement_batch_id);
CREATE INDEX ix_rail_message_replay_of_id ON rail_message (replay_of_id);
ALTER TABLE rail_message ENABLE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON rail_message USING (tenant_id = current_setting('app.tenant_id')::uuid);
CREATE TRIGGER trg_rail_message_append_only BEFORE UPDATE OR DELETE ON rail_message FOR EACH ROW EXECUTE FUNCTION forbid_mutation();

-- Transactional outbox: events are written here in the same transaction as the
-- state change and relayed to Kafka by the outbox relay (Debezium).
CREATE TABLE outbox (
  id              uuid PRIMARY KEY DEFAULT uuidv7(),
  tenant_id       uuid NOT NULL,
  aggregate_type  varchar(64) NOT NULL,
  aggregate_id    uuid NOT NULL,
  event_type      varchar(128) NOT NULL,
  payload         jsonb NOT NULL,
  headers         jsonb NOT NULL DEFAULT '{}'::jsonb,
  created_at      timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX ix_outbox_created ON outbox (created_at);

-- Idempotency keys for POST requests (24h retention).
CREATE TABLE idempotency_key (
  tenant_id       uuid NOT NULL,
  key             varchar(128) NOT NULL,
  request_hash    varchar(64) NOT NULL,
  response_status integer,
  response_body   jsonb,
  created_at      timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (tenant_id, key)
);

-- Runtime access for the non-superuser application role (RLS does not apply to superusers).
DO $$
BEGIN
  IF EXISTS (SELECT FROM pg_roles WHERE rolname = 'meridian_app') THEN
    GRANT USAGE ON SCHEMA routing TO meridian_app;
    GRANT SELECT, INSERT, UPDATE, DELETE ON ALL TABLES IN SCHEMA routing TO meridian_app;
    ALTER DEFAULT PRIVILEGES IN SCHEMA routing GRANT SELECT, INSERT, UPDATE, DELETE ON TABLES TO meridian_app;
  END IF;
END $$;
